mapper.select:
SELECT COUNT(*) FROM knowledge_parse_job
WHERE knowledge_id = #{knowledgeId} AND status IN

    #{status}

SELECT COUNT(*) FROM knowledge_parse_job
WHERE document_id = #{documentId} AND status IN

    #{status}

SELECT DISTINCT index_version_id FROM knowledge_index_document
WHERE document_id = #{documentId}
ORDER BY index_version_id

SELECT d.id
FROM knowledge_document d
WHERE d.status = #{deletedStatus}
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_parse_job j
      WHERE j.document_id = d.id AND j.status IN

          #{status}

  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_index_document x WHERE x.document_id = d.id
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_artifact_generation g
      WHERE g.document_id = d.id AND g.status != #{cleanedStatus}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM knowledge_document_version v
      JOIN sys_oss o ON o.oss_id = v.oss_id
      WHERE v.document_id = d.id
  )
ORDER BY d.id
LIMIT #{limit}

mapper.delete:
DELETE o FROM knowledge_message_outbox o
JOIN knowledge_parse_job j ON j.id = o.job_id
WHERE j.document_id = #{documentId}
   OR (
       j.job_type = 'CLEANUP'
       AND j.idempotency_key IN (
           SELECT CONCAT('CLEANUP:', g.generation_id)
           FROM knowledge_artifact_generation g
           WHERE g.document_id = #{documentId}
       )
   )

DELETE j FROM knowledge_parse_job j
WHERE j.document_id = #{documentId}
   OR (
       j.job_type = 'CLEANUP'
       AND j.idempotency_key IN (
           SELECT CONCAT('CLEANUP:', g.generation_id)
           FROM knowledge_artifact_generation g
           WHERE g.document_id = #{documentId}
       )
   )

mapper.select:
SELECT i.id
FROM knowledge_index_version i
WHERE i.status = #{deletedStatus}
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_index_document d WHERE d.index_version_id = i.id
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_artifact_generation g
      WHERE g.index_version_id = i.id AND g.status != #{cleanedStatus}
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_parse_job j
      WHERE j.knowledge_id = i.knowledge_id
        AND j.target_index_version = i.index_version
        AND j.status IN

            #{status}

  )
ORDER BY i.id
LIMIT #{limit}

SELECT k.id
FROM knowledge_info k
WHERE k.del_flag = '1'
  AND NOT EXISTS (SELECT 1 FROM knowledge_document d WHERE d.knowledge_id = k.id)
  AND NOT EXISTS (SELECT 1 FROM knowledge_index_document x WHERE x.knowledge_id = k.id)
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_artifact_generation g
      WHERE g.knowledge_id = k.id AND g.status != #{cleanedStatus}
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_index_version i
      WHERE i.knowledge_id = k.id AND i.status != #{deletedStatus}
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_parse_job j
      WHERE j.knowledge_id = k.id AND j.status IN

          #{status}

  )
ORDER BY k.id
LIMIT #{limit}

mapper.delete:
DELETE o FROM knowledge_message_outbox o
JOIN knowledge_parse_job j ON j.id = o.job_id
WHERE j.knowledge_id = #{knowledgeId}
